INSERT INTO `Courses` (`course_id`, `course_title`, `description`, `image_url`) VALUES (2, 'تطوير تطبيقات الويب التفاعلية (Full-Stack)', 'ورشة عمل مكثفة لبناء تطبيقات الويب الحديثة باستخدام تقنيات الواجهات الأمامية والخوادم وقواعد البيانات.', '');
